<script>
(function() {
  const canvas = document.getElementById('table');
  const ctx = canvas.getContext('2d');

  const W = 800;
  const H = 400;
  const R = 12;
  const POCKET_R = 22;
  const FRICTION = 0.985;
  const MIN_SPEED = 0.5;
  const RAIL_WIDTH = 30;

  canvas.width = W;
  canvas.height = H;

  // Pocket positions
  const pockets = [
    { x: 0, y: 0 },
    { x: W / 2, y: 0 },
    { x: W, y: 0 },
    { x: 0, y: H },
    { x: W / 2, y: H },
    { x: W, y: H }
  ];

  // Ball colors (standard pool)
  const ballColors = [
    '#ffffff', // 0: cue
    '#f4d03f', // 1: yellow
    '#2e86c1', // 2: blue
    '#e74c3c', // 3: red
    '#8e44ad', // 4: purple
    '#e67e22', // 5: orange
    '#27ae60', // 6: green
    '#922b21', // 7: maroon
    '#1c1c1c', // 8: black
    '#f4d03f', // 9: yellow stripe
    '#2e86c1', // 10: blue stripe
    '#e74c3c', // 11: red stripe
    '#8e44ad', // 12: purple stripe
    '#e67e22', // 13: orange stripe
    '#27ae60', // 14: green stripe
    '#922b21'  // 15: maroon stripe
  ];

  let balls = [];
  let paused = false;
  let animId = null;
  let lastTime = null;

  // Aiming state
  let aiming = false;
  let aimStart = { x: 0, y: 0 };
  let aimCurrent = { x: 0, y: 0 };

  function createStandardRack() {
    const result = [];
    // Cue ball
    result.push({ x: W * 0.25, y: H / 2, vx: 0, vy: 0, cue: true });

    // Rack position (triangle)
    const startX = W * 0.7;
    const startY = H / 2;
    const spacing = R * 2.1;

    // Standard 8-ball rack order (8 in center)
    const rackOrder = [1, 2, 3, 8, 4, 5, 6, 7, 9, 10, 11, 12, 13, 14, 15];
    let idx = 0;
    for (let row = 0; row < 5; row++) {
      for (let col = 0; col <= row; col++) {
        const bx = startX + row * spacing * Math.cos(Math.PI / 6);
        const by = startY + (col - row / 2) * spacing;
        const ballNum = rackOrder[idx];
        result.push({
          x: bx,
          y: by,
          vx: 0,
          vy: 0,
          cue: false,
          color: ballColors[ballNum],
          number: ballNum,
          striped: ballNum > 8
        });
        idx++;
      }
    }
    return result;
  }

  function reset(ballsInput) {
    balls = [];
    if (ballsInput && ballsInput.length > 0) {
      for (let i = 0; i < ballsInput.length; i++) {
        const b = ballsInput[i];
        balls.push({
          x: b.x,
          y: b.y,
          vx: b.vx || 0,
          vy: b.vy || 0,
          cue: !!b.cue,
          potted: false,
          color: b.cue ? '#ffffff' : (ballColors[i] || '#cccccc'),
          number: i,
          striped: i > 8
        });
      }
    } else {
      balls = createStandardRack();
    }
    draw();
  }

  function step(dt) {
    if (dt <= 0) return;
    // Sub-step for accuracy
    const subSteps = 4;
    const subDt = dt / subSteps;

    for (let s = 0; s < subSteps; s++) {
      // Move balls
      for (let i = 0; i < balls.length; i++) {
        const b = balls[i];
        if (b.potted) continue;
        b.x += b.vx * subDt;
        b.y += b.vy * subDt;
      }

      // Wall collisions
      for (let i = 0; i < balls.length; i++) {
        const b = balls[i];
        if (b.potted) continue;

        // Check if near a pocket - if so, don't bounce off wall
        let nearPocket = false;
        for (let p = 0; p < pockets.length; p++) {
          const dx = b.x - pockets[p].x;
          const dy = b.y - pockets[p].y;
          if (Math.sqrt(dx * dx + dy * dy) < POCKET_R + R) {
            nearPocket = true;
            break;
          }
        }

        if (!nearPocket) {
          if (b.x - R < 0) { b.x = R; b.vx = Math.abs(b.vx); }
          if (b.x + R > W) { b.x = W - R; b.vx = -Math.abs(b.vx); }
          if (b.y - R < 0) { b.y = R; b.vy = Math.abs(b.vy); }
          if (b.y + R > H) { b.y = H - R; b.vy = -Math.abs(b.vy); }
        }
      }

      // Ball-to-ball collisions
      for (let i = 0; i < balls.length; i++) {
        if (balls[i].potted) continue;
        for (let j = i + 1; j < balls.length; j++) {
          if (balls[j].potted) continue;
          resolveBallCollision(balls[i], balls[j]);
        }
      }

      // Pocket detection
      for (let i = 0; i < balls.length; i++) {
        const b = balls[i];
        if (b.potted) continue;
        for (let p = 0; p < pockets.length; p++) {
          const dx = b.x - pockets[p].x;
          const dy = b.y - pockets[p].y;
          if (Math.sqrt(dx * dx + dy * dy) < POCKET_R) {
            b.potted = true;
            b.vx = 0;
            b.vy = 0;
            break;
          }
        }
      }
    }

    // Apply friction
    for (let i = 0; i < balls.length; i++) {
      const b = balls[i];
      if (b.potted) continue;
      b.vx *= FRICTION;
      b.vy *= FRICTION;
      const speed = Math.sqrt(b.vx * b.vx + b.vy * b.vy);
      if (speed < MIN_SPEED) {
        b.vx = 0;
        b.vy = 0;
      }
    }
  }

  function resolveBallCollision(a, b) {
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    const dist = Math.sqrt(dx * dx + dy * dy);
    const minDist = R * 2;

    if (dist < minDist && dist > 0) {
      // Normal vector
      const nx = dx / dist;
      const ny = dy / dist;

      // Relative velocity
      const dvx = a.vx - b.vx;
      const dvy = a.vy - b.vy;

      // Relative velocity along normal
      const dvn = dvx * nx + dvy * ny;

      // Only resolve if approaching
      if (dvn > 0) {
        // Equal mass elastic collision
        a.vx -= dvn * nx;
        a.vy -= dvn * ny;
        b.vx += dvn * nx;
        b.vy += dvn * ny;
      }

      // Separate balls
      const overlap = minDist - dist;
      const sepX = (overlap / 2 + 0.1) * nx;
      const sepY = (overlap / 2 + 0.1) * ny;
      a.x -= sepX;
      a.y -= sepY;
      b.x += sepX;
      b.y += sepY;
    }
  }

  function state() {
    return balls.map(b => ({
      x: b.x,
      y: b.y,
      vx: b.vx,
      vy: b.vy,
      potted: !!b.potted,
      cue: !!b.cue
    }));
  }

  function shoot(vx, vy) {
    for (let i = 0; i < balls.length; i++) {
      if (balls[i].cue && !balls[i].potted) {
        balls[i].vx = vx;
        balls[i].vy = vy;
        break;
      }
    }
  }

  function draw() {
    // Table background (felt)
    ctx.fillStyle = '#0d6b3a';
    ctx.fillRect(0, 0, W, H);

    // Felt texture (subtle)
    ctx.fillStyle = 'rgba(0,0,0,0.03)';
    for (let i = 0; i < W; i += 4) {
      for (let j = 0; j < H; j += 4) {
        if (Math.random() < 0.3) {
          ctx.fillRect(i, j, 2, 2);
        }
      }
    }

    // Rails
    ctx.fillStyle = '#5c3a1e';
    // Top rail
    ctx.fillRect(0, 0, W, 6);
    // Bottom rail
    ctx.fillRect(0, H - 6, W, 6);
    // Left rail
    ctx.fillRect(0, 0, 6, H);
    // Right rail
    ctx.fillRect(W - 6, 0, 6, H);

    // Rail inner edge (cushion)
    ctx.strokeStyle = '#2d8a4e';
    ctx.lineWidth = 3;
    ctx.strokeRect(3, 3, W - 6, H - 6);

    // Pockets
    for (let p = 0; p < pockets.length; p++) {
      ctx.beginPath();
      ctx.arc(pockets[p].x, pockets[p].y, POCKET_R, 0, Math.PI * 2);
      ctx.fillStyle = '#111';
      ctx.fill();
      ctx.beginPath();
      ctx.arc(pockets[p].x, pockets[p].y, POCKET_R - 2, 0, Math.PI * 2);
      ctx.fillStyle = '#000';
      ctx.fill();
    }

    // Head string line (faint)
    ctx.beginPath();
    ctx.setLineDash([5, 5]);
    ctx.moveTo(W * 0.25, 6);
    ctx.lineTo(W * 0.25, H - 6);
    ctx.strokeStyle = 'rgba(255,255,255,0.1)';
    ctx.lineWidth = 1;
    ctx.stroke();
    ctx.setLineDash([]);

    // Draw balls
    for (let i = 0; i < balls.length; i++) {
      const b = balls[i];
      if (b.potted) continue;
      drawBall(b);
    }

    // Draw aim line
    if (aiming) {
      const cueBall = getCueBall();
      if (cueBall && !cueBall.potted) {
        const dx = cueBall.x - aimCurrent.x;
        const dy = cueBall.y - aimCurrent.y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist > 5) {
          const nx = dx / dist;
          const ny = dy / dist;

          // Aim line (dotted, in shot direction)
          ctx.beginPath();
          ctx.setLineDash([6, 4]);
          ctx.moveTo(cueBall.x, cueBall.y);
          ctx.lineTo(cueBall.x + nx * 300, cueBall.y + ny * 300);
          ctx.strokeStyle = 'rgba(255,255,255,0.7)';
          ctx.lineWidth = 2;
          ctx.stroke();
          ctx.setLineDash([]);

          // Power indicator (line from cue ball to mouse)
          ctx.beginPath();
          ctx.moveTo(cueBall.x, cueBall.y);
          ctx.lineTo(aimCurrent.x, aimCurrent.y);
          ctx.strokeStyle = 'rgba(255,100,100,0.8)';
          ctx.lineWidth = 3;
          ctx.stroke();

          // Power text
          const power = Math.min(dist / 200, 1);
          ctx.fillStyle = '#fff';
          ctx.font = '12px Arial';
          ctx.fillText('Power: ' + Math.round(power * 100) + '%', cueBall.x + 15, cueBall.y - 20);
        }
      }
    }
  }

  function drawBall(b) {
    // Shadow
    ctx.beginPath();
    ctx.arc(b.x + 2, b.y + 2, R, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(0,0,0,0.3)';
    ctx.fill();

    // Ball body
    ctx.beginPath();
    ctx.arc(b.x, b.y, R, 0, Math.PI * 2);
    ctx.fillStyle = b.color || '#fff';
    ctx.fill();

    // Stripe for balls 9-15
    if (b.striped) {
      ctx.beginPath();
      ctx.arc(b.x, b.y, R, 0, Math.PI * 2);
      ctx.fillStyle = '#fff';
      ctx.fill();
      // Color band
      ctx.beginPath();
      ctx.rect(b.x - R, b.y - R * 0.45, R * 2, R * 0.9);
      ctx.clip();
      ctx.beginPath();
      ctx.arc(b.x, b.y, R, 0, Math.PI * 2);
      ctx.fillStyle = b.color;
      ctx.fill();
      ctx.restore();
      ctx.save();
    }

    // Highlight
    ctx.beginPath();
    ctx.arc(b.x - R * 0.3, b.y - R * 0.3, R * 0.35, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(255,255,255,0.4)';
    ctx.fill();

    // Border
    ctx.beginPath();
    ctx.arc(b.x, b.y, R, 0, Math.PI * 2);
    ctx.strokeStyle = 'rgba(0,0,0,0.3)';
    ctx.lineWidth = 1;
    ctx.stroke();

    // Number (for non-cue balls)
    if (!b.cue && b.number !== undefined && b.number > 0) {
      ctx.fillStyle = '#fff';
      ctx.beginPath();
      ctx.arc(b.x, b.y, R * 0.4, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#000';
      ctx.font = 'bold ' + Math.round(R * 0.7) + 'px Arial';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(b.number, b.x, b.y + 1);
    }
  }

  function getCueBall() {
    for (let i = 0; i < balls.length; i++) {
      if (balls[i].cue) return balls[i];
    }
    return null;
  }

  // Mouse handling
  function getMousePos(e) {
    const rect = canvas.getBoundingClientRect();
    return {
      x: (e.clientX - rect.left) * (W / rect.width),
      y: (e.clientY - rect.top) * (H / rect.height)
    };
  }

  canvas.addEventListener('mousedown', function(e) {
    const pos = getMousePos(e);
    const cue = getCueBall();
    if (!cue || cue.potted) return;

    const dx = pos.x - cue.x;
    const dy = pos.y - cue.y;
    const dist = Math.sqrt(dx * dx + dy * dy);

    if (dist < R * 2.5) {
      aiming = true;
      aimStart = { x: pos.x, y: pos.y };
      aimCurrent = { x: pos.x, y: pos.y };
    }
  });

  canvas.addEventListener('mousemove', function(e) {
    if (!aiming) return;
    aimCurrent = getMousePos(e);
    draw();
  });

  canvas.addEventListener('mouseup', function(e) {
    if (!aiming) return;
    aiming = false;

    const cue = getCueBall();
    if (!cue || cue.potted) return;

    const dx = cue.x - aimCurrent.x;
    const dy = cue.y - aimCurrent.y;
    const dist = Math.sqrt(dx * dx + dy * dy);

    if (dist > 10) {
      const power = Math.min(dist / 200, 1);
      const maxSpeed = 800; // px/sec
      const speed = power * maxSpeed;
      const nx = dx / dist;
      const ny = dy / dist;
      shoot(nx * speed, ny * speed);
    }
    draw();
  });

  canvas.addEventListener('mouseleave', function(e) {
    if (aiming) {
      aiming = false;
      draw();
    }
  });

  // Touch support
  canvas.addEventListener('touchstart', function(e) {
    e.preventDefault();
    const touch = e.touches[0];
    const mouseEvent = new MouseEvent('mousedown', {
      clientX: touch.clientX,
      clientY: touch.clientY
    });
    canvas.dispatchEvent(mouseEvent);
  });

  canvas.addEventListener('touchmove', function(e) {
    e.preventDefault();
    const touch = e.touches[0];
    const mouseEvent = new MouseEvent('mousemove', {
      clientX: touch.clientX,
      clientY: touch.clientY
    });
    canvas.dispatchEvent(mouseEvent);
  });

  canvas.addEventListener('touchend', function(e) {
    e.preventDefault();
    const mouseEvent = new MouseEvent('mouseup', {});
    canvas.dispatchEvent(mouseEvent);
  });

  // Animation loop
  function gameLoop(timestamp) {
    if (paused) {
      animId = requestAnimationFrame(gameLoop);
      return;
    }
    if (lastTime === null) lastTime = timestamp;
    let dt = (timestamp - lastTime) / 1000;
    lastTime = timestamp;

    // Cap dt to avoid spiral of death
    if (dt > 0.05) dt = 0.05;

    step(dt);
    draw();
    updateStatus();

    animId = requestAnimationFrame(gameLoop);
  }

  function updateStatus() {
    const statusEl = document.getElementById('status');
    const potted = balls.filter(b => b.potted && !b.cue).length;
    const total = balls.filter(b => !b.cue).length;
    const cuePotted = balls.find(b => b.cue && b.potted);
    let text = 'Balls potted: ' + potted + '/' + total;
    if (cuePotted) text += ' | ⚠ Cue ball scratched!';
    statusEl.textContent = text;
  }

  function pause() {
    paused = true;
  }

  function resume() {
    paused = false;
    lastTime = null;
  }

  // Reset button
  document.getElementById('resetBtn').addEventListener('click', function() {
    reset();
  });

  // Expose sim API
  window.sim = {
    W: W,
    H: H,
    R: R,
    reset: reset,
    step: step,
    state: state,
    shoot: shoot,
    pause: pause,
    resume: resume
  };

  // Initialize
  ctx.save();
  reset();
  ctx.restore();
  animId = requestAnimationFrame(gameLoop);
})();
</script>
</body>
</html>
